contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry that exercises create with parameters and checks the invariant.
    // We take encodedParameters and ownedBy as inputs and also an operator flag to decide
    // whether this contract should be set as a program operator before calling create.
    // Because onlyProgramOperator checks programOperators[msg.sender], and msg.sender
    // will be this test contract, we may toggle programOperators by calling c through
    // functions available on C: programOperators is a public mapping, so there is an
    // autogenerated getter programOperators(address) view returns (bool), but there is
    // no setter except direct manipulation of c by its owner. The factory c is freshly
    // deployed and owned by this test's deployer in the harness; however test constraints
    // say this contract deployed c, so this InvMutTest is the owner of c. Thus we can
    // set programOperators[this] by calling c.transferOwnership etc. But transferOwnership
    // requires onlyOwner; owner() is the deployer (this contract) so we can call it.
    // We'll therefore set programOperators[msg.sender] by calling into c via the
    // storage mapping is not directly settable; but given constraints of P, there is no
    // explicit setter for programOperators. To work around this, we assert two cases:
    // if programOperators(this) is false then create must revert with the program operator error;
    // if it's true then create must succeed (given other preconditions) and return nonzero address
    // and factory owner remains unchanged.

    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        // read preconditions and factory owner
        address factoryOwner = c.owner(); if (__ESBMC_reverted()) return;
        bool beforeIsOperator = c.programOperators(address(this)); if (__ESBMC_reverted()) return;

        // ensure required globals: read current implementation and alloSettings
        address impl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address settings = c.alloSettings(); if (__ESBMC_reverted()) return;

        bool reverted;
        address created;
        // perform the call and capture revert status and result
        address addr = c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            created = address(0);
        } else {
            reverted = false;
            created = addr;
        }

        // General rule:
        // - If caller is not a program operator, create must revert.
        // - If caller is a program operator but roundImplementation or alloSettings is zero, create must revert.
        // - Otherwise create must NOT revert, must return a nonzero address, and must not change factory owner.
        assert(
            (
                (!beforeIsOperator && reverted)
                ||
                (beforeIsOperator && (impl == address(0) || settings == address(0)) && reverted)
                ||
                (beforeIsOperator && impl != address(0) && settings != address(0) && !reverted && created != address(0) && c.owner() == factoryOwner)
            )
        );
    }

    receive() external payable {}
}

